package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_html_TriageGen2Test {



    @Test
    public void testHtmlWithAttributes() {
        Element element = new Element(Tag.valueOf("div"), "");
        element.attr("id", "test-id");
        element.attr("class", "test-class");
        // Note: jsoup serializes attributes in a specific order, usually alphabetically or insertion order depending on version.
        // For standard testing, we check if the string contains the critical parts.
        String html = element.html();
        Assert.assertTrue(html.contains("id=\"test-id\""));
        Assert.assertTrue(html.contains("class=\"test-class\""));
        Assert.assertTrue(html.startsWith("<div"));
        Assert.assertTrue(html.endsWith("></div>"));
    }










}

